{"path": "rest_api.py", "content": "import json


class RestAPI:
    def __init__(self, database=None):
        self.users = {}
        for user in (database or {}).get("users", []):
            self.users[user["name"]] = {
                "name": user["name"],
                "owes": dict(user.get("owes", {})),
                "owed_by": dict(user.get("owed_by", {})),
            }

    def _user(self, name):
        user = self.users[name]
        balance = sum(user["owed_by"].values()) - sum(user["owes"].values())
        return {
            "name": user["name"],
            "owes": dict(user["owes"]),
            "owed_by": dict(user["owed_by"]),
            "balance": balance,
        }

    def _users(self, names):
        return {"users": [self._user(n) for n in sorted(names) if n in self.users]}

    @staticmethod
    def _parse(payload):
        if payload is None:
            return None
        if isinstance(payload, (str, bytes)):
            return json.loads(payload) if payload else None
        return payload

    def get(self, url, payload=None):
        data = self._parse(payload)
        if url == "/users":
            if data and "users" in data:
                return json.dumps(self._users(data["users"]))
            return json.dumps(self._users(self.users))
        raise ValueError(f"unknown url: {url}")

    def post(self, url, payload=None):
        data = self._parse(payload) or {}
        if url == "/add":
            name = data["user"]
            if name in self.users:
                raise ValueError("user already exists")
            self.users[name] = {"name": name, "owes": {}, "owed_by": {}}
            return json.dumps(self._user(name))
        if url == "/iou":
            lender, borrower = data["lender"], data["borrower"]
            amount = data["amount"]
            if lender not in self.users or borrower not in self.users:
                raise ValueError("unknown user")
            if lender == borrower:
                raise ValueError("lender and borrower must differ")
            self._add_debt(lender, borrower, amount)
            return json.dumps(self._users([lender, borrower]))
        raise ValueError(f"unknown url: {url}")

    def _add_debt(self, lender, borrower, amount):
        """Record that borrower owes lender `amount`, netting existing debts."""
        lend, borr = self.users[lender], self.users[borrower]
        # Net debt: positive means borrower owes lender.
        net = (
            lend["owed_by"].pop(borrower, 0)
            - lend["owes"].pop(borrower, 0)
            + amount
        )
        borr["owes"].pop(lender, None)
        borr["owed_by"].pop(lender, None)
        if net > 0:
            lend["owed_by"][borrower] = net
            borr["owes"][lender] = net
        elif net < 0:
            lend["owes"][borrower] = -net
            borr["owed_by"][lender] = -net
